/** A Turn's size class by estimated tokens, smallest first. */
export type Bucket = "tiny" | "small" | "medium" | "large" | "huge";

/**
 * Exclusive upper bound of each bounded bucket, ascending; a lower bound is
 * the previous bucket's upper bound, inclusive. `huge` has no upper bound.
 */
const BELOW: ReadonlyArray<readonly [Bucket, number]> = [
	["tiny", 350],
	["small", 1800],
	["medium", 7000],
	["large", 24000],
];

/** The bucket a Turn of `tokens` estimated tokens falls in. */
export function bucketOf(tokens: number): Bucket {
	for (const [bucket, below] of BELOW) if (tokens < below) return bucket;
	return "huge";
}

