import { describe, expect, test } from "bun:test";

import { bucketOf, histogram, turnSizes } from "./budget-table.ts";
import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";

describe("bucketOf", () => {
	test.each([
		[0, "tiny"],
		[349, "tiny"],
		[350, "small"],
		[1799, "small"],
		[1800, "medium"],
		[6999, "medium"],
		[7000, "large"],
		[23999, "large"],
		[24000, "huge"],
		[Number.MAX_SAFE_INTEGER, "huge"],
	] as const)("%p tokens is %p", (tokens, bucket) => {
		expect(bucketOf(tokens)).toBe(bucket);
	});

	test.each([-1, -0.5, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY])(
		"rejects %p with a RangeError",
		(tokens) => {
			expect(() => bucketOf(tokens)).toThrow(RangeError);
		},
	);
});

describe("turnSizes", () => {
	// Sizes differ by an order of magnitude so a dropped, merged or reordered
	// Turn shows up in the result.
	const leading: HarnessMessage = { role: "assistant", content: "x".repeat(4000) };
	const firstPrompt: HarnessMessage = { role: "user", content: "What is a Turn?" };
	const firstReply: HarnessMessage = { role: "assistant", content: "a".repeat(40) };
	const secondPrompt: HarnessMessage = { role: "user", content: "And a Budget?" };
	const secondReply: HarnessMessage = { role: "assistant", content: "b".repeat(400) };
	const messages = [leading, firstPrompt, firstReply, secondPrompt, secondReply];

	test("sizes each prompted Turn over its prompt and reply, in order", () => {
		expect(turnSizes(messages)).toEqual([
			approximateTokens([firstPrompt, firstReply]),
			approximateTokens([secondPrompt, secondReply]),
		]);
	});

	test("drops the messages before the first user prompt", () => {
		expect(turnSizes(messages)).toEqual(turnSizes(messages.slice(1)));
	});
});

describe("histogram", () => {
	test("counts the sample's sizes per bucket, largest bucket first", () => {
		expect(histogram([120, 90, 2400, 400, 8000])).toEqual([
			{ bucket: "large", count: 1 },
			{ bucket: "medium", count: 1 },
			{ bucket: "small", count: 1 },
			{ bucket: "tiny", count: 2 },
		]);
	});

	test("leaves out huge when no size reaches it, but keeps other empty buckets", () => {
		expect(histogram([23999, 23999, 349])).toEqual([
			{ bucket: "large", count: 2 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 1 },
		]);
	});

	test("an empty list has a zero entry for every bucket but huge", () => {
		expect(histogram([])).toEqual([
			{ bucket: "large", count: 0 },
			{ bucket: "medium", count: 0 },
			{ bucket: "small", count: 0 },
			{ bucket: "tiny", count: 0 },
		]);
	});
});

