import type { HarnessMessage } from "./messages.ts";
import { approximateTokens } from "./tokens.ts";
import { reconstructTurns } from "./turns.ts";

/** Turn-size bucket names, smallest first. */
export const BUCKETS = ["tiny", "small", "medium", "large", "huge"] as const;

/** A Turn's size class by estimated tokens. */
export type Bucket = (typeof BUCKETS)[number];

/**
 * Inclusive lower bound of each bucket, ascending in `BUCKETS` order; a
 * bucket's exclusive upper bound is the next bucket's lower bound, so `huge`
 * has none.
 */
const FROM: Record<Bucket, number> = {
	tiny: 0,
	small: 350,
	medium: 1800,
	large: 7000,
	huge: 24000,
};

/** What a size in each bucket is multiplied by to give its weighted size. */
const WEIGHT: Record<Bucket, number> = {
	tiny: 0.5,
	small: 1,
	medium: 1.25,
	large: 1.5,
	huge: 2.25,
};

/**
 * The bucket whose token range holds `tokens`; lower bounds are inclusive.
 * @throws RangeError if `tokens` is negative or not finite.
 */
export function bucketOf(tokens: number): Bucket {
	if (!Number.isFinite(tokens) || tokens < 0) {
		throw new RangeError(`Turn size must be a finite, non-negative token count, got ${tokens}`);
	}
	let bucket: Bucket = BUCKETS[0];
	for (const next of BUCKETS) if (tokens >= FROM[next]) bucket = next;
	return bucket;
}

/**
 * Estimated tokens of each Turn in `messages`, in order: one per Turn that
 * `reconstructTurns` finds, less a promptless leading one.
 *
 * Leading-Turn rule: messages before the first user prompt (a system prompt,
 * say) are grouped by `reconstructTurns` into a Turn with no prompt. That
 * Turn answers no user and is dropped, so its messages are not counted. Only
 * a leading Turn can be promptless; every later Turn starts at a user prompt.
 * The test is the first message's role, not an empty `prompt`, so a user
 * prompt with no text still starts a counted Turn.
 */
export function turnSizes(messages: HarnessMessage[]): number[] {
	const turns = reconstructTurns(messages);
	const promptless = turns[0]?.messages[0]?.role !== "user";
	return (promptless ? turns.slice(1) : turns).map((turn) => approximateTokens(turn.messages));
}

/**
 * How many of `sizes` fall in each bucket, largest bucket first. Every bucket
 * has an entry, with count 0 when empty, except `huge`, which is left out
 * when no size reaches it.
 * @throws RangeError if a size is negative or not finite, as `bucketOf`.
 */
export function histogram(sizes: number[]): { bucket: Bucket; count: number }[] {
	const counts: Record<Bucket, number> = { tiny: 0, small: 0, medium: 0, large: 0, huge: 0 };
	for (const size of sizes) counts[bucketOf(size)] += 1;
	return BUCKETS.toReversed()
		.filter((bucket) => bucket !== "huge" || counts.huge > 0)
		.map((bucket) => ({ bucket, count: counts[bucket] }));
}

/** The plain, unweighted sum of `sizes`; 0 for none. */
export function totalOf(sizes: number[]): number {
	let total = 0;
	for (const size of sizes) total += size;
	return total;
}

/**
 * Each size times its bucket's weight, parallel to `sizes`. Not rounded.
 * @throws RangeError if a size is negative or not finite, as `bucketOf`.
 */
export function weighted(sizes: number[]): number[] {
	return sizes.map((size) => size * WEIGHT[bucketOf(size)]);
}

