// suite: TT-5082
import { describe, expect, test } from "bun:test";

import { weighted } from "./budget-table.ts";

describe("weighted", () => {
	// The weight changes at each threshold, so both sides of each are checked.
	test.each([
		[0, 0],
		[349, 174.5],
		[350, 350],
		[1799, 1799],
		[1800, 2250],
		[6999, 8748.75],
		[7000, 10500],
		[23999, 35998.5],
		[24000, 54000],
	])("%p tokens weighs %p", (size, weight) => {
		expect(weighted([size])).toEqual([weight]);
	});

	test("keeps the order of the sizes", () => {
		expect(weighted([30000, 120, 8000, 2400, 400])).toEqual([67500, 60, 12000, 3000, 400]);
	});

	test("does not round fractional weighted sizes", () => {
		expect(weighted([1801, 7001])).toEqual([2251.25, 10501.5]);
		expect(weighted([1])).toEqual([0.5]);
	});

	test("an empty list weighs nothing", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => weighted([120, -1])).toThrow(RangeError);
	});
});

