	test("rounds other weighted sizes to the nearest multiple of 10", () => {
		// 0.5, 364, 366 and 2252.5 before rounding.
		expect(weighted([1, 364, 366, 1802])).toEqual([0, 360, 370, 2250]);
	});

	test("an empty list weighs nothing", () => {
		expect(weighted([])).toEqual([]);
	});

	test("rejects a negative size with a RangeError", () => {
		expect(() => weighted([120, -1])).toThrow(RangeError);
