describe("bucketTotals", () => {
	test("sums each bucket's weighted sizes, rounding each Turn before summing", () => {
		// Two tiny 349s weigh 170 each (174.5 rounded), so 340; summing first
		// would give 350. large has no Turn and totals 0.
