// owner: OWN-9314
import { bucketTotals, formatCount, histogram, labelOf } from "./budget-table.ts";

/**
 * The bucket table for a Conversation's Turn sizes, one string per row: a
 * header, then a row per histogram entry in histogram order giving the
 * bucket's label, its Turn count and its weighted total. Columns are joined
 * by ` | ` with no padding.
 * @throws RangeError if a size is negative or not finite, as `bucketOf`.
 */
export function renderTable(sizes: number[]): string[] {
	const totals = bucketTotals(sizes);
	return [
		"bucket | turns | weighted",
		...histogram(sizes).map(({ bucket, count }) =>
			[labelOf(bucket), count, formatCount(totals.get(bucket) ?? 0)].join(" | "),
		),
	];
}

