/**
…
 */
export function summaryLine(sizes: number[], budget: number): string {
	if (!Number.isFinite(budget) || budget <= 0) {
		throw new RangeError(`Budget must be a positive, finite token count, got ${budget}`);
	}
	const peak = histogram(sizes).find(({ count }) => count > 0)?.bucket ?? "none";
	const total = totalOf(sizes);
	return [
		`turns=${sizes.length}`,
		`total=${total}`,
		`used=${Math.floor((total * 100) / budget)}%`,
		`peak=${peak}`,
		`over=${sizes.filter((size) => size > 9000).length}`,
	].join(" · ");
}

